// env.json dan web/kakao_config.js ni yaratadi (Kakao JS SDK'ni yuklaydi).
// Ishlatish: dart run tool/gen_web_env.dart
import 'dart:convert';
import 'dart:io';

void main() {
  final env = jsonDecode(File('env.json').readAsStringSync()) as Map<String, dynamic>;
  final key = (env['KAKAO_JS_KEY'] as String?) ?? '';
  if (key.isEmpty) {
    stderr.writeln('env.json da KAKAO_JS_KEY yo\'q');
    exit(1);
  }
  // Kakao SDK o'zi ham document.write ishlatadi — shuning uchun sinxron yuklash xavfsiz.
  File('web/kakao_config.js').writeAsStringSync(
    '// AUTO-GENERATED by tool/gen_web_env.dart — commit qilmang.\n'
    'document.write(\'<script src="https://dapi.kakao.com/v2/maps/sdk.js?appkey=$key"><\\/script>\');\n',
  );
  stdout.writeln('web/kakao_config.js yaratildi');
}
